+        def bwcSubProjectFolder = testProjectDir.newFolder("distribution", "bwc", "minor")
+        new File(bwcSubProjectFolder, 'bwc-marker.txt') << "bwc=minor"
+        new File(bwcSubProjectFolder, 'build.gradle') << """
