+        def result = WiremockFixture.withWireMock(mockRepoUrl, mockedContent) { server ->
+            buildFile << repositoryMockSetup(server, jdkVendor, jdkVersion)
+            gradleRunner('getJdk', '-i', '-g', testProjectDir.newFolder().toString()).build()
+        }
+
+        then:
