+                vendor = '$VENDOR_ADOPTOPENJDK'
+                version = '$ADOPT_JDK_VERSION'
+                platform = "$platform"
+                architecture = "x64"
+              }
+            }
+
+            tasks.register("getJdk") {
+                dependsOn jdks.myJdk
+                doLast {
+                    println "JDK HOME: " + jdks.myJdk
+                }
+            }
+        """
