+                "Project requires Java version of " + minimumCompilerVersion + " or newer but Gradle JAVA_HOME is " + currentVersion
+            );
+        }
+    }
+
+    private File findRuntimeJavaHome() {
+        String runtimeJavaProperty = System.getProperty("runtime.java");
