+    public FileCollection getChangelogs() {
+        return changelogs;
+    }
+
+    public void setChangelogs(FileCollection files) {
+        this.changelogs.setFrom(files);
+    }
+
+    @InputFile
+    public RegularFileProperty getReleaseNotesIndexTemplate() {
+        return releaseNotesIndexTemplate;
+    }
